  tools.exec_command({cmd:"rg -n 'MailDetails(Draft|Blob)|_ownerEncSessionKey' --glob '!node_modules/**' --glob '!vendor/**' .",workdir:"/app",max_output_tokens:12000})
]); for (const x of r) text(x.status === "fulfilled" ? x.value.output : String(x.reason));

